// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint104 amount) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        uint256 beforeBal = c.getBalance(actor);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 afterBal = c.getBalance(actor);
        assertTrue(afterBal == beforeBal + amount);
    }
}
